(()=>{
const cal=document.getElementById('calendarGrid');if(!cal)return;const $=id=>document.getElementById(id),arrival=$('arrival'),departure=$('departure'),guests=$('guests'),estimate=$('rentalEstimate'),prev=$('calendarPrev'),next=$('calendarNext'),title=$('calendarMonth');const today=new Date();today.setHours(12,0,0,0);const stamp=d=>d.getFullYear()+'-'+String(d.getMonth()+1).padStart(2,'0')+'-'+String(d.getDate()).padStart(2,'0'),date=s=>new Date(s+'T12:00:00'),nights=(a,b)=>Math.round((date(b)-date(a))/86400000),occupied=d=>[8,9,17,25].includes(d.getDate())||([13,14].includes(d.getDate())&&d.getMonth()%2===0);const blocked=s=>occupied(date(s)),between=(a,b)=>{for(let d=date(a);d<date(b);d.setDate(d.getDate()+1))if(occupied(d))return true;return false};const minimum=stamp(today);arrival.min=minimum;departure.min=minimum;let month=new Date(today.getFullYear(),today.getMonth(),1,12),start='',end='';
function summary(message){if(message){estimate.textContent=message;return}estimate.textContent=start&&end?nights(start,end)+' nights × $195 = $'+(nights(start,end)*195).toLocaleString('en-US')+' sample subtotal. No reservation is created.':start?'Arrival selected. Choose a departure at least two nights later.':'Choose your dates to preview the featured cabin.'}
function update(){arrival.value=start;departure.value=end;if(start){const d=date(start);d.setDate(d.getDate()+2);departure.min=stamp(d)}summary();render()}
function choose(s){if(!start||end||s<=start){start=s;end=''}else if(nights(start,s)<2){summary('Choose a departure at least two nights after your arrival.');return}else if(between(start,s)){summary('Those dates contain a sample occupied night. Please select another range.');return}else end=s;update()}
function render(){title.textContent=month.toLocaleDateString('en-US',{month:'long',year:'numeric'}).toUpperCase();cal.replaceChildren();['SUN','MON','TUE','WED','THU','FRI','SAT'].forEach(s=>{const el=document.createElement('span');el.className='weekday';el.textContent=s;cal.append(el)});const first=new Date(month.getFullYear(),month.getMonth(),1,12),last=new Date(month.getFullYear(),month.getMonth()+1,0,12);for(let i=0;i<first.getDay();i++){const el=document.createElement('span');el.className='empty';cal.append(el)}for(let n=1;n<=last.getDate();n++){const d=new Date(month.getFullYear(),month.getMonth(),n,12),s=stamp(d),b=document.createElement('button');b.type='button';b.textContent=n;b.setAttribute('aria-label',d.toDateString()+(occupied(d)?', sample occupied':''));b.disabled=d<today||occupied(d);if(occupied(d))b.classList.add('occupied');if(s===start||s===end)b.classList.add('selected-date');else if(start&&end&&s>start&&s<end)b.classList.add('in-range');if(s===minimum)b.classList.add('today');b.addEventListener('click',()=>choose(s));cal.append(b)}prev.disabled=month.getFullYear()===today.getFullYear()&&month.getMonth()===today.getMonth()}
prev.addEventListener('click',()=>{month=new Date(month.getFullYear(),month.getMonth()-1,1,12);render()});next.addEventListener('click',()=>{month=new Date(month.getFullYear(),month.getMonth()+1,1,12);render()});
function inputChanged(){const a=arrival.value,b=departure.value;if(a&&(a<minimum||blocked(a))){summary('Please choose an unoccupied future arrival.');return}if(b&&blocked(b)){summary('That departure is marked occupied in the demo.');return}if(a&&b&&(nights(a,b)<2||between(a,b))){summary('Please select at least two nights without sample occupied dates.');return}start=a;end=b;update()}
arrival.addEventListener('change',inputChanged);departure.addEventListener('change',inputChanged);
const action=document.querySelector('.rental-date-summary .rental-main-cta');action.addEventListener('click',()=>{const q=new URLSearchParams();if(start)q.set('arrival',start);if(end)q.set('departure',end);q.set('guests',guests.value);action.href='/moss/inquire/?'+q.toString()});
render();summary();
})();
